    assign subtractive_axi_arcache = (apb4m_32b_ar_gnt_subtractive ? apb4m_32b_ar.cache : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_32b_ar.cache : '0);
    assign subtractive_axi_arprot = (apb4m_32b_ar_gnt_subtractive ? apb4m_32b_ar.prot : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_32b_ar.prot : '0);
    assign subtractive_axi_arqos = (apb4m_32b_ar_gnt_subtractive ? apb4m_32b_ar.qos : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_32b_ar.qos : '0);
    assign subtractive_axi_arregion = (apb4m_32b_ar_gnt_subtractive ? apb4m_32b_ar.region : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_32b_ar.region : '0);
    assign subtractive_axi_aruser = (apb4m_32b_ar_gnt_subtractive ? apb4m_32b_ar.user : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_32b_ar.user : '0);
    assign subtractive_axi_arvalid = apb4m_32b_ar_gnt_subtractive || apb5m_32b_ar_gnt_subtractive;

    // Rready (slave → owning master, by rid_bridge_id)
    assign subtractive_axi_rready = ((subtractive_axi_rid_bridge_id == 0) && subtractive_axi_rid_valid ? apb4m_32b_rready : '0) |
        ((subtractive_axi_rid_bridge_id == 1) && subtractive_axi_rid_valid ? apb5m_32b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (apb4m_32b_ar_gnt_subtractive ? apb4m_bridge_id_ar : '0) |
        (apb5m_32b_ar_gnt_subtractive ? apb5m_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // apb4m 32b path -> mem, lregs, periph, subtractive
    logic [1:0] apb4m_32b_wdest_mem [16];
    logic [4:0] apb4m_32b_wdest_wptr, apb4m_32b_wdest_rptr;
    wire [1:0] apb4m_32b_wdest_enc = apb4m_32b_aw_to_lregs ? 2'd1 : apb4m_32b_aw_to_periph ? 2'd2 : apb4m_32b_aw_to_subtractive ? 2'd3 : 2'd0;
    wire apb4m_32b_wdest_push = apb4m_32b_awvalid && apb4m_32b_awready;
    wire apb4m_32b_wdest_pop  = apb4m_32b_wvalid && apb4m_32b_wready && apb4m_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            apb4m_32b_wdest_wptr <= '0;
            apb4m_32b_wdest_rptr <= '0;
        end else begin
            if (apb4m_32b_wdest_push) begin
                apb4m_32b_wdest_mem[apb4m_32b_wdest_wptr[3:0]] <= apb4m_32b_wdest_enc;
                apb4m_32b_wdest_wptr <= apb4m_32b_wdest_wptr + 1'b1;
            end
            if (apb4m_32b_wdest_pop) begin
                apb4m_32b_wdest_rptr <= apb4m_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire apb4m_32b_wdest_valid = (apb4m_32b_wdest_wptr != apb4m_32b_wdest_rptr);
    wire [1:0] apb4m_32b_wdest_head = apb4m_32b_wdest_mem[apb4m_32b_wdest_rptr[3:0]];
    assign apb4m_32b_w_to_mem = apb4m_32b_wdest_valid && (apb4m_32b_wdest_head == 2'd0);
    assign apb4m_32b_w_to_lregs = apb4m_32b_wdest_valid && (apb4m_32b_wdest_head == 2'd1);
    assign apb4m_32b_w_to_periph = apb4m_32b_wdest_valid && (apb4m_32b_wdest_head == 2'd2);
    assign apb4m_32b_w_to_subtractive = apb4m_32b_wdest_valid && (apb4m_32b_wdest_head == 2'd3);

    // apb5m 32b path -> mem, lregs, periph, subtractive
    logic [1:0] apb5m_32b_wdest_mem [16];
    logic [4:0] apb5m_32b_wdest_wptr, apb5m_32b_wdest_rptr;
    wire [1:0] apb5m_32b_wdest_enc = apb5m_32b_aw_to_lregs ? 2'd1 : apb5m_32b_aw_to_periph ? 2'd2 : apb5m_32b_aw_to_subtractive ? 2'd3 : 2'd0;
