    assign apb5m_32b_w_to_mem = apb5m_32b_wdest_valid && (apb5m_32b_wdest_head == 2'd0);
    assign apb5m_32b_w_to_lregs = apb5m_32b_wdest_valid && (apb5m_32b_wdest_head == 2'd1);
    assign apb5m_32b_w_to_periph = apb5m_32b_wdest_valid && (apb5m_32b_wdest_head == 2'd2);
    assign apb5m_32b_w_to_subtractive = apb5m_32b_wdest_valid && (apb5m_32b_wdest_head == 2'd3);

    // ================================================================
    // Response MUXes (OR together all slave responses)
