    assign apb4m_32b_b.id = 
        ((mem_axi_bid_bridge_id == 0) && mem_axi_bid_valid ? mem_axi_bid : '0) |
        ((lregs_axi_bid_bridge_id == 0) && lregs_axi_bid_valid ? lregs_axi_bid : '0) |
